{
  "name": "@siming-org/opencode-plugin",
  "version": "0.1.20",
  "description": "opencode v2 plugin for siming: registers MCP task tools (siming_*), onboarding guide skill, siming_cli/siming_refresh tools, and global+project skills/subagents pulled live from the siming server",
  "type": "module",
  "keywords": [
    "opencode-plugin"
  ],
  "exports": {
    "./server": "./dist/server/index.js"
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "jsonc-parser": "^3.3.1",
    "zod": "^4.4.3",
    "@siming-org/cli": "0.8.21"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.35",
    "@types/node": "^26.0.0",
    "@typescript/native-preview": "^7.0.0-dev.20260518.1",
    "tsx": "^4.20.0",
    "typescript": "^5.8.0",
    "vitest": "^2.1.9"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsgo --noEmit",
    "test": "vitest run",
    "clean": "rm -rf dist"
  }
}
